sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float hueCenter;
uniform float hueRange;
uniform float satMin;
uniform float satMax;
uniform float valMin;
uniform float valMax;
uniform float softness;
uniform float invert;
uniform float showMatte;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 rgb2hsv(float3 c) {
    float4 K = float4(0.0, -0.3333333, 0.6666667, -1.0);
    float4 p = mix(float4(c.b, c.g, K.w, K.z), float4(c.g, c.b, K.x, K.y), step(c.b, c.g));
    float4 q = mix(float4(p.x, p.y, p.w, c.r), float4(c.r, p.y, p.z, p.x), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    return float3(abs(q.z + (q.w - q.y) / (6.0 * d + 0.0000001)), d / (q.x + 0.0000001), q.x);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 h = rgb2hsv(s);
    float dh = abs(fract(h.x - hueCenter / 360.0 + 0.5) - 0.5) * 360.0;
    float mh = 1.0 - smoothstep(hueRange * (1.0 - softness), hueRange + 0.001, dh);
    float ms = smoothstep(satMin - softness * 0.2, satMin + softness * 0.2 + 0.001, h.y) * (1.0 - smoothstep(satMax - softness * 0.2, satMax + softness * 0.2 + 0.001, h.y));
    float mv = smoothstep(valMin - softness * 0.2, valMin + softness * 0.2 + 0.001, h.z) * (1.0 - smoothstep(valMax - softness * 0.2, valMax + softness * 0.2 + 0.001, h.z));
    float match = mh * ms * mv;
    float keep = invert > 0.5 ? match : 1.0 - match;
    float4 r = c * keep;
    if (showMatte > 0.5) r = float4(float3(keep) * c.a, c.a);
    return fin(c, r, opacity);
}
